CONTENT.vi.projects.unshift({"id": "fun-studio-testing", "role": "Tester Intern", "company": "Công ty TNHH Công nghệ Kết nối Ý Nghĩa", "time": "10/2023 – 4/2024", "tags": ["Tester Intern", "Brand Website", "Franchise Operations", "UI/UX"], "image": "/assets/fun-studio.png", "approved": true, "type": "Nền tảng số", "name": "Kiểm thử Website doanh nghiệp & vận hành nội bộ", "desc": "Kiểm thử 2 nền tảng web: website thương hiệu hướng đến khách hàng và đối tác nhượng quyền, cùng hệ thống quản lý vận hành dành cho doanh nghiệp và các đơn vị nhượng quyền.", "facts": ["Nền tảng: Web · 2 hệ thống", "Quy mô nhóm: 13 người — 1 PM, 1 PO, 6 Developer, 2 Tester, 2 BA, 1 Designer"], "sections": [{"title": "Mô tả dự án", "text": "Dự án gồm 2 nền tảng web. Website công khai giới thiệu thương hiệu Fun Studio, dịch vụ chụp ảnh và cửa hàng; đồng thời cung cấp thông tin để đối tác tìm hiểu mô hình và đăng ký tư vấn nhượng quyền. Hệ thống vận hành nội bộ được doanh nghiệp và các đơn vị nhượng quyền sử dụng để quản lý doanh thu, giao dịch, nhân sự, nhượng quyền, lỗi và voucher; đồng thời hỗ trợ theo dõi quy trình vận hành."}, {"title": "Đóng góp trong dự án", "items": ["Xây dựng và thực hiện test case UI/UX cho website công khai của Fun Studio.", "Kiểm tra nội dung và điều hướng phục vụ 2 nhóm người dùng: đối tác/nhà đầu tư nhượng quyền (B2B) và khách hàng chụp ảnh (B2C).", "Kiểm thử các khu vực giới thiệu dịch vụ, cửa hàng, tin tức, gallery và thông tin liên hệ/đăng ký nhượng quyền.", "Thực hiện test case cho 6 nhóm chức năng trên hệ thống vận hành: doanh thu, lịch sử giao dịch, nhượng quyền, nhân sự, quản lý lỗi và voucher."]}, {"title": "Kết quả đạt được", "items": ["01 website thương hiệu được kiểm thử về UI/UX.", "06 test case được thực hiện cho 06 chức năng trên hệ thống vận hành: doanh thu, lịch sử giao dịch, quản lý nhượng quyền, nhân sự, lỗi và voucher."]}]});

