Object.assign(CONTENT.vi.projects.find(p=>p.id==='photobooth-product'),{"name": "Phát triển sản phẩm Photobooth", "role": "Product Management Assistant", "detailRole": "Product Management Assistant", "time": "04/2024 – 03/2025", "coverImage": "/assets/fun-studio-pink.jpg", "desc": "Tham gia nghiên cứu, đề xuất và phát triển các tính năng cho ứng dụng Photobooth, đồng thời xây dựng các sản phẩm và concept trải nghiệm mới xoay quanh ứng dụng.", "highlights": "3 nhóm tính năng sản phẩm · Nhóm dự án 14 người", "facts": ["Nền tảng: Photobooth App · Merchandise Web App", "Quy mô đội ngũ: 14 người — 1 PM, 1 PO, 6 Developer, 2 Tester, 2 BA, 2 Designer"], "sections": [{"title": "Mô tả dự án", "text": "Dự án phát triển ứng dụng Photobooth kết nối với thiết bị chụp ảnh, cho phép người dùng chụp và tùy chỉnh hình ảnh. Bên cạnh các tính năng trong ứng dụng, đội ngũ phát triển nền tảng web cá nhân hóa merchandise bằng ảnh và các concept Photobooth kết hợp thiết bị, không gian thực tế và trải nghiệm số."}, {"title": "Công việc & Đóng góp trong dự án", "items": ["Nghiên cứu xu hướng thị trường, sản phẩm tương tự và nhu cầu người dùng để đề xuất ý tưởng sản phẩm và hướng phát triển.", "Hỗ trợ PM/PO xác định mục tiêu, chiến lược và lộ trình sản phẩm; theo dõi tiến độ và hỗ trợ phối hợp xử lý vấn đề.", "Tham gia cùng PM trong các buổi trao đổi với khách hàng để làm rõ yêu cầu và phối hợp với các nhóm nội bộ nhằm thống nhất hướng triển khai.", "Nghiên cứu các đầu vào cần thiết để phát triển sản phẩm mới, bao gồm nhà cung cấp, nguồn lực, yêu cầu vận hành và các bước triển khai.", "Tham gia đề xuất và phát triển tính năng chỉnh sửa khuôn mặt trực tiếp khi chụp, gồm làm mịn da, cân chỉnh tông màu và độ sáng da, tinh chỉnh đường nét khuôn mặt và xử lý khuyết điểm nhỏ.", "Tham gia phát triển tính năng chỉnh sửa ảnh và các bộ lọc màu lấy cảm hứng từ phong cách Retro và Y2K.", "Cùng đội ngũ phát triển tính năng trên web để cá nhân hóa merchandise bằng ảnh Photobooth, gồm quần áo, túi, ốp điện thoại và bình giữ nhiệt.", "Tham gia nghiên cứu và phát triển các concept Photobooth mới kết hợp thiết bị chụp ảnh, không gian thực tế và tính năng số."]}, {"title": "Đóng góp & Kết quả đạt được", "items": ["Tham gia phát triển 3 nhóm tính năng sản phẩm: chỉnh sửa ảnh và khuôn mặt, bộ lọc màu và cá nhân hóa merchandise.", "Góp phần phát triển các concept Photobooth, mở rộng trải nghiệm từ chụp ảnh số sang sản phẩm vật lý và không gian trải nghiệm trực tiếp.", "Hỗ trợ phối hợp giữa khách hàng, PM/PO và các nhóm nội bộ trong quá trình nghiên cứu sản phẩm, phát triển và theo dõi dự án."]}], "contributionTitles": ["Nghiên cứu thị trường & Đề xuất ý tưởng", "Hỗ trợ PM/PO & Lộ trình sản phẩm", "Phối hợp khách hàng & Đội ngũ", "Nguồn lực & Vận hành", "Tính năng chỉnh sửa khuôn mặt", "Chỉnh sửa ảnh & Bộ lọc màu", "Cá nhân hóa merchandise", "Concept Photobooth"]});
