Object.assign(CONTENT.en.projects.find(p=>p.id==='snap-ba'),{"translationPending": false, "desc": "Analyzed business requirements for Odoo ERP and three web platforms: a Warehouse Scanning Web App, a court booking website, and an event management website for Facolos and its franchise partners.", "tags": ["Odoo ERP", "CRM/Sales", "Warehouse Scanning", "Court Booking", "Event Management", "Business Analysis"], "domain": "ERP · Warehouse Operations · Court Booking · Event Management", "team": "12 members — 1 PM, 3 BAs, and 8 Developers", "scope": [["Odoo ERP", "2 modules — CRM/Sales and Warehouse."], ["Warehouse Scanning Web App", "A scanning application connected to Odoo for warehouse operations."], ["Court Booking Website", "For Facolos and its franchise partners to manage court bookings."], ["Event Management Website", "For Facolos and its franchise partners to create and manage events."]], "contributionIntro": "The project focused on building digital systems to support business management and operations. Odoo ERP was used to manage CRM/Sales and warehouse processes, while a Warehouse Scanning Web App connected to Odoo to help staff scan items and track goods processing. In parallel, court booking and event management websites were developed for Facolos and its franchise partners to manage activities across locations. Together, these platforms support business operations, marketing, communications, and coordination across the network.", "workGroups": [{"title": "Odoo ERP", "items": ["Gathered and clarified requirements; analyzed CRM/Sales, Warehouse, and related Accounting workflows.", "Defined business rules, documented process flows, and prepared functional specifications.", "Created User Stories, Acceptance Criteria, Change Requests, and process diagrams.", "Prepared role-based test cases and collaborated with Developers, Testers, and users to validate functionality.", "Supported UAT, prepared user guides, and answered business-related questions during implementation."]}, {"title": "Warehouse Scanning Web App and Websites", "items": ["Consulted stakeholders to understand user needs and workflows for each platform.", "Analyzed requirements, features, and business processes for the warehouse scanning app, court booking website, and event management website.", "Created screen mockups to illustrate interfaces and user flows and clarify requirements with the development team.", "Prepared test cases, supported testing, and recorded feedback and issues.", "Prepared user guides, supported UAT, and trained end users."]}], "workTitles": [["Requirements & Workflow Analysis", "Business Rules & Specifications", "User Stories & Process Diagrams", "Role-based Testing & Collaboration", "UAT & User Guides"], ["Stakeholder Consultation", "Requirements & Business Processes", "Screen Mockups & User Flows", "Test Cases & Feedback", "User Guides & End-user Training"]], "deliverableSummary": ["Analyzed 4 platforms: Odoo ERP and 3 web applications.", "Specified 2 Odoo modules: CRM/Sales and Warehouse.", "Completed 10 Odoo documents, including 8 specifications and 2 Change Requests.", "Created 184 Odoo User Stories/requirement items: 104 for CRM/Sales, 73 for Warehouse, and 7 for the Packaging Change Request.", "Prepared 6 role-based testing groups for Odoo: 3 for CRM/Sales and 3 for Warehouse.", "Conducted business analysis, created mockups and test cases, and prepared user guides for the Warehouse Scanning Web App and two websites."], "descriptions": [["Odoo ERP", "2 modules — CRM/Sales and Warehouse."], ["Warehouse Scanning Web App", "A scanning application connected to Odoo for warehouse operations."], ["Court Booking Website", "For Facolos and its franchise partners to manage court bookings."], ["Event Management Website", "For Facolos and its franchise partners to create and manage events."]]});
